500	## Memory Tool
501	
502	### Basic Usage
503	
504	```typescript
505	const response = await client.messages.create({
506	  model: "claude-opus-5",
507	  max_tokens: 16000,
508	  messages: [
509	    {
510	      role: "user",
511	      content: "Remember that my preferred language is TypeScript.",
512	    },
513	  ],
514	  tools: [{ type: "memory_20250818", name: "memory" }],
515	});
516	```
517	
518	### SDK Memory Helper
519	
520	Use `betaMemoryTool` with a `MemoryToolHandlers` implementation:
521	
522	```typescript
523	import {
524	  betaMemoryTool,
525	  type MemoryToolHandlers,
526	} from "@anthropic-ai/sdk/helpers/beta/memory";
527	
528	const handlers: MemoryToolHandlers = {
529	  async view(command) { ... },
530	  async create(command) { ... },
531	  async str_replace(command) { ... },
532	  async insert(command) { ... },
533	  async delete(command) { ... },
534	  async rename(command) { ... },
535	};
536	
537	const memory = betaMemoryTool(handlers);
538	
539	const runner = client.beta.messages.toolRunner({
540	  model: "claude-opus-5",
541	  max_tokens: 16000,
542	  tools: [memory],
543	  messages: [{ role: "user", content: "Remember my preferences" }],
544	});
545	
546	for await (const message of runner) {
547	  console.log(message);
548	}
549	```
550	
551	For full implementation examples, use WebFetch:
552	
553	- `https://github.com/anthropics/anthropic-sdk-typescript/blob/main/examples/tools-helpers-memory.ts`
554	
555	---
556	
557	## Structured Outputs
558	
559	### JSON Outputs (Zod - Recommended)
560	
561	```typescript
562	import Anthropic from "@anthropic-ai/sdk";
563	import { z } from "zod";
564	import { zodOutputFormat } from "@anthropic-ai/sdk/helpers/zod";
565	
566	const ContactInfoSchema = z.object({
567	  name: z.string(),
568	  email: z.string(),
569	  plan: z.string(),
570	  interests: z.array(z.string()),
571	  demo_requested: z.boolean(),
572	});
573	
574	const client = new Anthropic();
575	
576	const response = await client.messages.parse({
577	  model: "claude-opus-5",
578	  max_tokens: 16000,
579	  messages: [
580	    {
581	      role: "user",
582	      content:
583	        "Extract: Jane Doe (jane@co.com) wants Enterprise, interested in API and SDKs, wants a demo.",
584	    },
585	  ],
586	  output_config: {
587	    format: zodOutputFormat(ContactInfoSchema),
588	  },
589	});
590	
591	// parsed_output is null if parsing failed - assert or guard
592	console.log(response.parsed_output!.name); // "Jane Doe"
593	```
594	
595	### Strict Tool Use
596	
597	```typescript
598	const response = await client.messages.create({
599	  model: "claude-opus-5",
600	  max_tokens: 16000,
601	  messages: [
602	    {
603	      role: "user",
604	      content: "Book a flight to Tokyo for 2 passengers on March 15",
605	    },
606	  ],
607	  tools: [
608	    {
609	      name: "book_flight",
610	      description: "Book a flight to a destination",
611	      strict: true,
612	      input_schema: {
