    `SELECT d.*, s.name AS site_name, a.tag AS asset_tag, j.job_no FROM defects d JOIN sites s ON s.id = d.site_id LEFT JOIN assets a ON a.id = d.asset_id LEFT JOIN jobs j ON j.id = d.job_id
