      plan('nff', store, 'Quarterly refrigeration & AC service', 3, 4, ['refrigeration'], 'refrig', tags, store === 'nff-bury' ? 0 : store === 'nff-prestwich' ? 9 : 16, store === 'nff-bury' ? 'dave' : 'lee', 'Before 10:00 or after 20:00 on shop floor.');
