        const assetIds = q.all<{ asset_id: number }>('SELECT asset_id FROM ppm_plan_assets WHERE plan_id = ?', p.id).map((a) => a.asset_id);
        const eng = p.preferred_engineer_id ?? J.engineerFor(JSON.parse(p.required_skills));
