          columns={[
            { key: 's', label: 'Severity', render: (d: any) => <Badge tone={d.severity === 'unsafe' ? 'red' : d.severity === 'urgent' ? 'orange' : d.severity === 'recommended' ? 'amber' : 'neutral'}>{titleCase(d.severity)}</Badge> },
