  survey: 'bg-paper border-line-strong',
};

export default function Schedule() {
  const { user } = useAuth();
  const canEdit = perms(user).schedule;
  const [day, setDay] = useState(() => {
    const d = new Date();
    if (d.getDay() === 6) return addDays(d, 2);
    if (d.getDay() === 0) return addDays(d, 1);
    return d;
