                ['Ends', date(s.contract.ends_on)],
              ]} />
              {s.contract.sla.length > 0 && (
                <table className="mt-3 w-full text-xs">
                  <thead><tr className="text-left text-muted"><th className="py-1">Priority</th><th>Attend</th><th>Fix</th></tr></thead>
