              </ul>
            )}
          </div>
          <Button size="sm" variant="ghost" onClick={() => setLines([...lines, { description: '', qty: 1, unit_cost: 0 }])}>+ Non-catalogue item</Button>
          <ErrorNote error={err} />
        </div>
