18	        <div className="flex-1">
19	          <div className="text-sm font-semibold">{user?.name}</div>
20	          <div className="text-xs text-steel-100/70">{new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' })}</div>
21	        </div>
22	        <button onClick={() => setOpen(true)} className="rounded-md bg-navy-700 p-2" aria-label="Ask Frostline"><Sparkles className="size-5" /></button>
23	        {user?.role !== 'engineer' && <Link to="/" className="rounded-md bg-navy-700 p-2" aria-label="Desktop view"><Monitor className="size-5" /></Link>}
24	        <button onClick={logout} className="rounded-md p-2 hover:bg-navy-700" aria-label="Sign out"><LogOut className="size-5" /></button>
25	      </header>
26	      <main className="flex-1 pb-24">
27	        <Routes>
28	          <Route index element={<MyDay />} />
29	          <Route path="visits/:id" element={<VisitView />} />
30	          <Route path="van" element={<Van />} />
31	        </Routes>
32	      </main>
33	      <nav className="fixed right-0 bottom-0 left-0 z-20 mx-auto flex max-w-xl border-t border-line bg-white" style={{ paddingBottom: 'env(safe-area-inset-bottom, 0px)' }}>
34	        <Tab to="/m" icon={<CalendarDays className="size-5" />} label="My jobs" end />
35	        <Tab to="/m/van" icon={<Boxes className="size-5" />} label="Van stock" />
36	      </nav>
37	    </div>
38	  );
39	}
40	
41	const Tab = ({ to, icon, label, end }: { to: string; icon: ReactNode; label: string; end?: boolean }) => (
42	  <NavLink to={to} end={end} className={({ isActive }) => cx('flex flex-1 flex-col items-center gap-0.5 py-2.5 text-xs', isActive ? 'font-medium text-steel-600' : 'text-muted')}>
43	    {icon}
44	    {label}
45	  </NavLink>
46	);
47	
48	function MyDay() {
49	  const { user } = useAuth();
50	  const { data, isLoading } = useApi<any[]>('/me/visits', { refetchInterval: 60_000 });
51	  if (!user?.engineer_id) return <div className="p-6 text-sm text-muted">This view is for engineers. Sign in as an engineer (e.g. Dave Whittaker) to see their jobs.</div>;
52	  if (isLoading) return <Spinner />;
53	  const byDay = new Map<string, any[]>();
